/**
 * generated by stackra gen from src/config/i18n.config.ts (locales, fallbacks),
 * assets/lang/<locale>/web.json, src/overrides/marketing/leads/assets/lang/<locale>/leads.json and
 * the lang sections of the consumed manifests (commerce: catalogue; the pinned marketing: leads;
 * the pinned experience) — do not edit
 * Purpose: the complete typed key tree of the public site (its own `web::` namespace, with the
 *          derived keys of its classes, plus every consumed namespace a source or generated file
 *          references), the namespace loaders with overrides applied, the fallback chains,
 *          `loadMessages` (the root loader) and `translatorFor` (the route adapters' server-side
 *          `t`).
 * Boundary: a leaf is a branded `I18nKey`; a raw string is a type error. Derived keys follow
 *           `<module>::<kind>.<name>.<part>` (`web::errors.site_context_missing.message`,
 *           `web::enums.billing_interval.<code>`, `web::flags.pricing_yearly_first.label`,
 *           `catalogue::errors.product_not_found.message`); gen fails when one is missing in any
 *           locale. The pinned acme-platform namespaces keep the keys their revision publishes.
 *           Consumed namespaces are copied by gen into `.stackra/lang/`; gen fails on an `ar`
 *           plural missing any of `zero one two few many other`. A regional locale (`en-US`,
 *           `ar-SA`) loads only the files that exist for it, under its fallback chain: the
 *           base-language and default catalogues load first and the overlay's keys are merged over
 *           them, so a key missing from the overlay renders its base-language string.
 * Runtime: isomorphic
 */
import {
  formatMessage,
  keys,
  mergeCatalogues,
  type I18nKey,
  type LoadCatalogue,
  type Locale,
} from "@stackra/i18n";

export type { I18nKey };

