/**
 * Namespace → locale → loader, for the files that exist; `web` has the two regional overlays and
 * `leads` the site's overrides merged key by key (the `overrides` list below).
 */
export const loaders: Record<string, Partial<Record<Locale, LoadCatalogue>>> = {
  web: {
    en: () => import("#assets/lang/en/web.json"),
    "en-US": () => import("#assets/lang/en-US/web.json"),
    ar: () => import("#assets/lang/ar/web.json"),
    "ar-SA": () => import("#assets/lang/ar-SA/web.json"),
  },
  leads: {
    en: () => import("../lang/en/leads.json"),
    ar: () => import("../lang/ar/leads.json"),
  },
  catalogue: {
    en: () => import("../lang/en/catalogue.json"),
    ar: () => import("../lang/ar/catalogue.json"),
  },
  experience: {
    en: () => import("../lang/en/experience.json"),
    ar: () => import("../lang/ar/experience.json"),
  },
};

/** Overrides gen merged into the `.stackra/lang` copies, by namespace, locale and key. */
export const overrides = [
  {
    namespace: "leads",
    locale: "en",
    file: "src/overrides/marketing/leads/assets/lang/en/leads.json",
    keys: ["refusals.rate_limited", "refusals.captcha_failed"],
  },
  {
    namespace: "leads",
    locale: "ar",
    file: "src/overrides/marketing/leads/assets/lang/ar/leads.json",
    keys: ["refusals.rate_limited", "refusals.captcha_failed"],
  },
] as const;

/** Locales from i18n.config.ts; every base language provides every namespace (gen checks). */
export const locales = ["en", "en-US", "ar", "ar-SA"] as const;

/** i18n.config.ts `fallbacks`: the chain each locale falls back along, nearest first. */
export const fallbacks: Record<Locale, readonly Locale[]> = {
  "ar-SA": ["ar", "en"],
  ar: ["en"],
  "en-US": ["en"],
  en: [],
};

/** Loads the catalogues one request needs; `t()` resolves ICU messages from the merged result. */
export async function loadMessages(locale: Locale, names: string[]) {
  // farthest fallback first, so each nearer catalogue's keys win over it
  const chain = [...fallbacks[locale]].reverse().concat(locale);
  const loaded = await Promise.all(
    names.map(async (name) => {
      const files = chain.flatMap((code) => loaders[name]?.[code] ?? []);
      const catalogues = await Promise.all(files.map(async (load) => (await load()).default));
      return [name, mergeCatalogues(catalogues)] as const;
    }),
  );
  return Object.fromEntries(loaded) as Record<string, Record<string, unknown>>;
}

/** A server-side `t()` for one request's locale, used by the route adapters to translate `meta`. */
export async function translatorFor(locale: Locale, names: string[]) {
  const messages = await loadMessages(locale, names);
  return (key: I18nKey, values?: Record<string, unknown>) =>
    formatMessage(messages, key, values, locale);
}
